package org.codex.nfsugpreview;
import java.io.*;import java.util.*;
public final class HudCandidatesTest {public static void main(String[] args)throws Exception{int count,accepted=0,rejected=0,checks=0;try(DataInputStream in=new DataInputStream(new FileInputStream(args[0]))){if(in.readInt()!=0x3143484e)throw new AssertionError("Header");int banks=in.readInt();count=in.readInt();byte[][] vram=new byte[banks][98304],palette=new byte[banks][1024];for(int i=0;i<banks;i++){in.readFully(vram[i]);in.readFully(palette[i]);}for(int ci=0;ci<count;ci++){int bank=in.readInt(),display=in.readInt(),row=in.readInt(),blend=in.readInt(),brightness=in.readInt();int[] window=new int[6];for(int i=0;i<6;i++)window[i]=in.readInt();int[] wb=window.clone();byte[] oam=new byte[1024];in.readFully(oam);byte[] ob=oam.clone(),vb=vram[bank].clone(),pb=palette[bank].clone();boolean expected=in.readInt()!=0;int n=expected?240:0;int[] colors=new int[n],tags=new int[n];byte[] visible=new byte[n],backdrop=new byte[n];for(int i=0;i<n;i++)colors[i]=in.readInt();for(int i=0;i<n;i++)tags[i]=in.readInt();in.readFully(visible);in.readFully(backdrop);NativeHudCandidates.Row result=null;boolean good=true;try{result=NativeHudCandidates.prepare(vram[bank],palette[bank],oam,display,row,window,blend,brightness);}catch(IllegalArgumentException invalid){good=false;}if(good!=expected)throw new AssertionError("Acceptance "+ci);if(!Arrays.equals(wb,window)||!Arrays.equals(ob,oam)||!Arrays.equals(vb,vram[bank])||!Arrays.equals(pb,palette[bank]))throw new AssertionError("Input mutation");if(good){accepted++;if(!Arrays.equals(colors,result.colors())||!Arrays.equals(tags,result.tags())||!Arrays.equals(visible,result.visible())||!Arrays.equals(backdrop,result.backdrop()))throw new AssertionError("Combined candidate "+ci);byte[] copy=result.visible();copy[0]^=1;if(!Arrays.equals(visible,result.visible()))throw new AssertionError("Borrowed output");checks+=960;}else rejected++;}if(in.read()!=-1)throw new AssertionError("Trailing cases");}System.out.println("PASS_HUD_CANDIDATES cases="+count+" accepted="+accepted+" rejected="+rejected+" exact_checks="+checks+" inputs_immutable=true output_owned=true");}}
